b4) AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 27 AND `stackable` <=> 1 AND `stacksize` <=> 100 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 285 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 11 AND `delay` <=> 0 AND `range` <=> 100 AND `slots` <=> 4194304 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0))<>11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC141 native item identity/range drift'; END IF;
